339→        bt:'全天', bs:'冬季', tip:'冬季海景+温泉的对比构图。' },
340→      { id:51, name:'田横岛', area:'即墨', lng:120.7200, lat:36.3200, emoji:'🏝️', cat:['sea','aerial'], tags:['海岛','航拍','小众'], tc:['aerial'], r:[], pro:true,
341→        desc:'即墨最出名的海岛，视觉中国有航拍收录。岛上保留着原始风貌，周围海水清澈。航拍展示海岛全貌非常壮观。',
342→        bt:'上午', bs:'夏秋', tip:'航拍最出片，岛上原始风貌值得探索。' }
343→    ];
344→
345→    const CC = { sea:'#4db6ac', bldg:'#ffa726', sunset:'#ff8a65', sunrise:'#ffb74d', night:'#9577d5', rom:'#ec708c', aerial:'#9fa8da' };
346→    const AO = ['市南','崂山','黄岛','市北','李沧','即墨'];
347→    const AN = { '市南':'市南区 · 老城与海岸线', '崂山':'崂山区 · 山海风光', '黄岛':'西海岸 · 金沙滩日落', '市北':'市北区 · 烟火人文', '李沧':'李沧区 · 园林花卉', '即墨':'即墨区 · 海岛温泉' };
348→
349→    let map=null, markers={}, curF='all', curA='all', curR=null, searchT='';
350→
351→    function renderList() {
352→      const list = document.getElementById('spotList');
353→      list.innerHTML = '';
354→      let f = spots.filter(s => {
355→        if (curF!=='all' && !s.cat.includes(curF)) return false;
356→        if (curA!=='all' && s.area!==curA) return false;
357→        if (curR && (!s.r || !s.r.includes(curR))) return false;
358→        if (searchT && !s.name.includes(searchT) && !s.desc.includes(searchT)) return false;
359→        return true;
360→      });
361→      document.getElementById('spotCount').textContent = `${f.length} 个机位`;
362→      document.getElementById('sn').textContent = f.length;
363→      const g = {};
364→      f.forEach(s => { if (!g[s.area]) g[s.area]=[]; g[s.area].push(s); });
365→      AO.forEach(a => {
366→        if (!g[a]) return;
367→        const t = document.createElement('div'); t.className='sgt';
368→        t.textContent = `── ${AN[a]} (${g[a].length}) ──`;
369→        list.appendChild(t);
370→        g[a].forEach(s => {
371→          const c = document.createElement('div'); c.className='spot-card'; c.dataset.id=s.id;
372→          const th = s.tags.map((t,i) => `<span class="stag t-${s.tc[i]||'sea'}">${t}</span>`).join('');
373→          c.innerHTML = `<div class="sico" style="background:${CC[s.cat[0]]}18">${s.emoji}</div>
374→            <div class="sinfo"><div class="sname">${s.name}${s.hot?'<span class="hot">热门</span>':''}${s.pro?'<span class="pro">专业收录</span>':''}</div>
375→            <div class="sdesc">${s.desc}</div><div class="stags">${th}</div></div>`;
376→          c.addEventListener('click', () => flyTo(s.id));
377→          list.appendChild(c);
378→        });
379→      });
380→    }
381→
382→    document.querySelectorAll('.ftab').forEach(t => t.addEventListener('click', () => {
383→      document.querySelectorAll('.ftab').forEach(x=>x.classList.remove('active'));
384→      t.classList.add('active'); curF=t.dataset.f; renderList(); updateM();
385→    }));
386→    document.querySelectorAll('.atab').forEach(t => t.addEventListener('click', () => {
387→      document.querySelectorAll('.atab').forEach(x=>x.classList.remove('active'));
388→      t.classList.add('active'); curA=t.dataset.a; renderList(); updateM();
389→    }));
390→    document.querySelectorAll('.rbtn').forEach(t => t.addEventListener('click', () => {
391→      const was = t.classList.contains('active');
392→      document.querySelectorAll('.rbtn').forEach(x=>x.classList.remove('active'));
393→      curR = was ? null : t.dataset.r;
394→      if (curR) t.classList.add('active');
395→      renderList(); updateM();
396→    }));
397→    document.getElementById('searchBox').addEventListener('input', e => { searchT=e.target.value; renderList(); updateM(); });
398→
399→    function initMap() {
400→      map = L.map('map', { center:[36.062,120.420], zoom:11, zoomControl:false });
401→      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { subdomains:'abcd', maxZoom:19 }).addTo(map);
402→      L.control.zoom({ position:'topright' }).addTo(map);
403→      spots.forEach(s => {
404→        const ic = L.divIcon({ className:'',
405→          html:`<div class="cm"><div class="ml">${s.name}</div><div class="mp" style="background:${CC[s.cat[0]]};${s.pro?'border:2px solid rgba(171,71,188,0.5);':''}"><span class="me">${s.emoji}</span></div></div>`,
406→          iconSize:[30,38], iconAnchor:[15,38], popupAnchor:[0,-38] });
407→        const m = L.marker([s.lat,s.lng], {icon:ic}).addTo(map);
408→        m.on('click', () => showInfo(s));
409→        markers[s.id] = m;
410→      });
411→    }
412→
413→    function updateM() {
414→      spots.forEach(s => {
415→        const m = markers[s.id]; if (!m) return;
416→        let show = true;
417→        if (curF!=='all' && !s.cat.includes(curF)) show=false;
418→        if (curA!=='all' && s.area!==curA) show=false;
419→        if (curR && (!s.r || !s.r.includes(curR))) show=false;
420→        if (searchT && !s.name.includes(searchT) && !s.desc.includes(searchT)) show=false;
421→        show ? map.addLayer(m) : map.removeLayer(m);
422→      });
423→    }
424→
425→    function flyTo(id) {
426→      const s = spots.find(x=>x.id===id); if (!s) return;
427→      map.flyTo([s.lat,s.lng], 15, { duration:0.8 });
428→      document.querySelectorAll('.spot-card').forEach(c=>c.classList.remove('active'));
429→      const c = document.querySelector(`.spot-card[data-id="${id}"]`);
430→      if (c) { c.classList.add('active'); c.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
431→      showInfo(s);
432→    }
433→
434→    function showInfo(s) {
435→      const p = document.getElementById('infoPanel');
436→      document.getElementById('iname').innerHTML = `${s.emoji} ${s.name} ${s.hot?'<span class="hot">热门</span>':''} ${s.pro?'<span class="pro">视觉中国/500px</span>':''}`;
437→      document.getElementById('idesc').textContent = s.desc;
438→      document.getElementById('idets').innerHTML = `
439→        <div class="idet"><div class="idet-l">📸 最佳时间</div><div class="idet-v">${s.bt}</div></div>
440→        <div class="idet"><div class="idet-l">🗓️ 最佳季节</div><div class="idet-v">${s.bs}</div></div>
441→        <div class="idet"><div class="idet-l">💡 拍摄建议</div><div class="idet-v">${s.tip}</div></div>`;
442→      const nav = `https://uri.amap.com/marker?position=${s.lng},${s.lat}&name=${encodeURIComponent(s.name)}&callnative=1`;
443→      const view = `https://www.amap.com/search?query=${encodeURIComponent(s.name+' 青岛')}&city=370200`;
444→      document.getElementById('iacts').innerHTML = `
445→        <a href="${nav}" target="_blank" class="ibtn p">📍 高德导航</a>
446→        <a href="${view}" target="_blank" class="ibtn">🗺️ 高德查看</a>`;
447→      p.classList.add('show');
448→    }
449→
450→    document.getElementById('iclose').addEventListener('click', () => { document.getElementById('infoPanel').classList.remove('show'); });
451→
452→    renderList();
453→    initMap();
454→  </script>
455→</body>
456→</html>
