content:
  1→<!DOCTYPE html>
  2→<html lang="zh-CN">
  3→<head>
  4→  <meta charset="UTF-8">
  5→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  6→  <title>青岛摄影机位地图 · 全收录</title>
  7→  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
  8→  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
  9→  <style>
 10→    * { margin: 0; padding: 0; box-sizing: border-box; }
 11→    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; background: #0a1628; color: #e8e8e8; height: 100vh; overflow: hidden; }
 12→    .header { background: linear-gradient(135deg, #1a2a3a 0%, #0d1b2a 100%); padding: 10px 18px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(100, 200, 255, 0.12); box-shadow: 0 4px 20px rgba(0,0,0,0.3); flex-shrink: 0; }
 13→    .header h1 { font-size: 17px; font-weight: 600; background: linear-gradient(90deg, #4fc3f7, #81d4fa, #b3e5fc); -webkit-background-clip: text; -webkit-text-fill-color: transparent; letter-spacing: 1px; }
 14→    .header .sub { font-size: 11px; color: #546e7a; margin-top: 2px; }
 15→    .header-right { display: flex; align-items: center; gap: 8px; }
 16→    .search-box { background: rgba(255,255,255,0.06); border: 1px solid rgba(100, 200, 255, 0.12); border-radius: 18px; padding: 5px 12px; font-size: 12px; color: #e0e0e0; width: 170px; outline: none; }
 17→    .search-box::placeholder { color: #455a64; }
 18→    .search-box:focus { border-color: #4fc3f7; }
 19→    .badge { background: rgba(79, 195, 247, 0.12); border: 1px solid rgba(79, 195, 247, 0.25); border-radius: 16px; padding: 4px 12px; font-size: 11px; color: #4fc3f7; white-space: nowrap; }
 20→    .container { display: flex; height: calc(100vh - 54px); }
 21→    .sidebar { width: 350px; background: #111d2e; border-right: 1px solid rgba(100, 200, 255, 0.08); overflow-y: auto; flex-shrink: 0; display: flex; flex-direction: column; }
 22→    .sidebar::-webkit-scrollbar { width: 5px; }
 23→    .sidebar::-webkit-scrollbar-track { background: transparent; }
 24→    .sidebar::-webkit-scrollbar-thumb { background: rgba(79, 195, 247, 0.25); border-radius: 3px; }
 25→    .sidebar-header { padding: 10px 14px; border-bottom: 1px solid rgba(100, 200, 255, 0.06); position: sticky; top: 0; background: #111d2e; z-index: 100; }
 26→    .filter-tabs { display: flex; gap: 5px; flex-wrap: wrap; }
 27→    .ftab { padding: 3px 10px; border-radius: 14px; font-size: 11px; cursor: pointer; border: 1px solid rgba(100, 200, 255, 0.12); background: transparent; color: #78909c; transition: all 0.2s; user-select: none; white-space: nowrap; }
 28→    .ftab:hover { border-color: #4fc3f7; color: #4fc3f7; }
 29→    .ftab.active { background: rgba(79, 195, 247, 0.18); border-color: #4fc3f7; color: #4fc3f7; }
 30→    .route-sec { padding: 8px 14px; border-bottom: 1px solid rgba(100, 200, 255, 0.06); }
 31→    .route-title { font-size: 11px; font-weight: 600; color: #546e7a; margin-bottom: 6px; letter-spacing: 1px; }
 32→    .route-btns { display: flex; gap: 5px; flex-wrap: wrap; }
 33→    .rbtn { padding: 3px 9px; border-radius: 10px; font-size: 11px; cursor: pointer; border: 1px solid rgba(255, 200, 100, 0.15); background: rgba(255, 200, 100, 0.06); color: #b8860b; transition: all 0.2s; }
 34→    .rbtn:hover { background: rgba(255, 200, 100, 0.15); border-color: #daa520; }
 35→    .rbtn.active { background: rgba(255, 200, 100, 0.22); border-color: #daa520; color: #ffd700; }
 36→    .spot-list { padding: 4px; flex: 1; overflow-y: auto; }
 37→    .sgt { font-size: 10px; color: #455a64; padding: 6px 12px 3px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; }
 38→    .spot-card { display: flex; align-items: flex-start; gap: 10px; padding: 8px 12px; border-radius: 10px; cursor: pointer; transition: all 0.2s; margin-bottom: 1px; border: 1px solid transparent; }
 39→    .spot-card:hover { background: rgba(79, 195, 247, 0.06); }
 40→    .spot-card.active { background: rgba(79, 195, 247, 0.1); border-color: rgba(79, 195, 247, 0.18); }
 41→    .sico { width: 34px; height: 34px; border-radius: 9px; display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
 42→    .sinfo { flex: 1; min-width: 0; }
 43→    .sname { font-size: 13px; font-weight: 600; color: #e0e0e0; margin-bottom: 2px; display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
 44→    .hot { font-size: 9px; padding: 1px 5px; border-radius: 6px; background: rgba(255, 82, 82, 0.18); color: #ff5252; font-weight: 500; }
 45→    .pro { font-size: 9px; padding: 1px 5px; border-radius: 6px; background: rgba(171, 71, 188, 0.18); color: #ab47bc; font-weight: 500; }
 46→    .sdesc { font-size: 11px; color: #607d8b; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
 47→    .stags { display: flex; gap: 3px; margin-top: 3px; flex-wrap: wrap; }
 48→    .stag { font-size: 9px; padding: 1px 6px; border-radius: 7px; }
 49→    .t-sea { background: rgba(77, 182, 172, 0.12); color: #4db6ac; }
 50→    .t-sunrise { background: rgba(255, 183, 77, 0.12); color: #ffb74d; }
 51→    .t-sunset { background: rgba(255, 138, 101, 0.12); color: #ff8a65; }
 52→    .t-night { background: rgba(149, 119, 213, 0.12); color: #9577d5; }
 53→    .t-bldg { background: rgba(255, 167, 38, 0.12); color: #ffa726; }
 54→    .t-rom { background: rgba(236, 112, 140, 0.12); color: #ec708c; }
 55→    .t-film { background: rgba(129, 199, 132, 0.12); color: #81c784; }
 56→    .t-niche { background: rgba(100, 181, 246, 0.12); color: #64b5f6; }
 57→    .t-insta { background: rgba(240, 98, 146, 0.12); color: #f06292; }
 58→    .t-aerial { background: rgba(159, 168, 210, 0.12); color: #9fa8da; }
 59→    .map-box { flex: 1; position: relative; }
 60→    #map { width: 100%; height: 100%; }
 61→    .leaflet-control-attribution { display: none !important; }
 62→    .info-panel { position: absolute; bottom: 14px; left: 14px; width: 380px; max-height: 58vh; overflow-y: auto; background: rgba(17, 29, 46, 0.97); backdrop-filter: blur(12px); border-radius: 14px; padding: 18px; border: 1px solid rgba(100, 200, 255, 0.12); display: none; animation: su 0.3s ease; z-index: 1000; }
 63→    @keyframes su { from { transform: translateY(16px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
 64→    .info-panel.show { display: block; }
 65→    .ih { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
 66→    .iname { font-size: 16px; font-weight: 600; color: #4fc3f7; }
 67→    .iclose { width: 24px; height: 24px; border-radius: 50%; border: 1px solid rgba(100, 200, 255, 0.18); background: transparent; color: #78909c; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 13px; }
 68→    .idesc { font-size: 12px; color: #90a4ae; line-height: 1.5; margin-bottom: 12px; }
 69→    .idets { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 12px; }
 70→    .idet { background: rgba(79, 195, 247, 0.06); border-radius: 8px; padding: 8px; }
 71→    .idet-l { font-size: 10px; color: #546e7a; margin-bottom: 3px; }
 72→    .idet-v { font-size: 12px; color: #cfd8dc; font-weight: 500; }
 73→    .iacts { display: flex; gap: 6px; }
 74→    .ibtn { flex: 1; padding: 7px 8px; border-radius: 8px; border: 1px solid rgba(100, 200, 255, 0.15); background: transparent; color: #4fc3f7; font-size: 11px; cursor: pointer; text-align: center; text-decoration: none; display: flex; align-items: center; justify-content: center; gap: 4px; transition: all 0.2s; }
 75→    .ibtn:hover { background: rgba(79, 195, 247, 0.12); }
 76→    .ibtn.p { background: rgba(79, 195, 247, 0.18); border-color: #4fc3f7; }
 77→    .stats { position: absolute; top: 12px; right: 12px; background: rgba(17, 29, 46, 0.9); backdrop-filter: blur(10px); border-radius: 10px; padding: 8px 12px; border: 1px solid rgba(100, 200, 255, 0.1); display: flex; gap: 12px; z-index: 999; }
 78→    .si { text-align: center; }
 79→    .sn { font-size: 16px; font-weight: 700; color: #4fc3f7; }
 80→    .sl { font-size: 9px; color: #546e7a; }
 81→    .area-f { position: absolute; top: 12px; left: 12px; background: rgba(17, 29, 46, 0.9); backdrop-filter: blur(10px); border-radius: 10px; padding: 8px 12px; border: 1px solid rgba(100, 200, 255, 0.1); z-index: 999; }
 82→    .at { font-size: 10px; color: #546e7a; margin-bottom: 5px; font-weight: 600; }
 83→    .atabs { display: flex; gap: 3px; flex-wrap: wrap; }
 84→    .atab { padding: 3px 8px; border-radius: 8px; font-size: 10px; cursor: pointer; border: 1px solid rgba(100, 200, 255, 0.1); background: transparent; color: #546e7a; transition: all 0.2s; }
 85→    .atab:hover { border-color: #4fc3f7; color: #4fc3f7; }
 86→    .atab.active { background: rgba(79, 195, 247, 0.18); border-color: #4fc3f7; color: #4fc3f7; }
 87→    .legend { position: absolute; bottom: 14px; right: 14px; background: rgba(17, 29, 46, 0.9); backdrop-filter: blur(10px); border-radius: 10px; padding: 10px 12px; border: 1px solid rgba(100, 200, 255, 0.1); z-index: 999; }
 88→    .lt { font-size: 10px; color: #546e7a; margin-bottom: 5px; font-weight: 600; }
 89→    .li { display: flex; align-items: center; gap: 6px; margin-bottom: 3px; }
 90→    .ldot { width: 8px; height: 8px; border-radius: 50%; }
 91→    .ltx { font-size: 10px; color: #78909c; }
 92→    .cm { position: relative; cursor: pointer; }
 93→    .mp { width: 30px; height: 30px; border-radius: 50% 50% 50% 0; position: absolute; transform: rotate(-45deg); display: flex; align-items: center; justify-content: center; box-shadow: 0 3px 10px rgba(0,0,0,0.3); border: 2px solid rgba(255,255,255,0.2); }
 94→    .mp .me { transform: rotate(45deg); font-size: 14px; }
 95→    .ml { position: absolute; top: -20px; left: 50%; transform: translateX(-50%); background: rgba(17, 29, 46, 0.9); color: #cfd8dc; padding: 1px 6px; border-radius: 6px; font-size: 9px; white-space: nowrap; border: 1px solid rgba(100, 200, 255, 0.12); }
