486→      L.control.zoom({ position:'topright' }).addTo(map);
487→      spots.forEach(s => {
488→        const ic = L.divIcon({ className:'',
489→          html:`<div class="cm"><div class="ml">${s.name}</div><div class="mp" style="background:${CC[s.cat[0]]};${s.pro?'border:2px solid rgba(171,71,188,0.5);':''}"><span class="me">${s.emoji}</span></div></div>`,
490→          iconSize:[30,38], iconAnchor:[15,38], popupAnchor:[0,-38] });
491→        const m = L.marker([s.lat,s.lng], {icon:ic}).addTo(map);
492→        m.on('click', () => showInfo(s));
493→        markers[s.id] = m;
494→      });
495→    }
496→
497→    function updateM() {
498→      spots.forEach(s => {
499→        const m = markers[s.id]; if (!m) return;
500→        let show = true;
501→        if (curF!=='all' && !s.cat.includes(curF)) show=false;
502→        if (curA!=='all' && s.area!==curA) show=false;
503→        if (curR && (!s.r || !s.r.includes(curR))) show=false;
504→        if (searchT && !s.name.includes(searchT) && !s.desc.includes(searchT)) show=false;
505→        show ? map.addLayer(m) : map.removeLayer(m);
506→      });
507→    }
