512→      document.querySelectorAll('.spot-card').forEach(c=>c.classList.remove('active'));
513→      const c = document.querySelector(`.spot-card[data-id="${id}"]`);
514→      if (c) { c.classList.add('active'); c.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
