429→    const CC = { sea:'#4db6ac', bldg:'#ffa726', sunset:'#ff8a65', sunrise:'#ffb74d', night:'#9577d5', rom:'#ec708c', aerial:'#9fa8da' };
430→    const AO = ['市南','崂山','黄岛','市北','李沧','即墨'];
431→    const AN = { '市南':'市南区 · 老城与海岸线', '崂山':'崂山区 · 山海风光', '黄岛':'西海岸 · 金沙滩日落', '市北':'市北区 · 烟火人文', '李沧':'李沧区 · 园林花卉', '即墨':'即墨区 · 海岛温泉' };
432→
433→    let map=null, markers={}, curF='all', curA='all', curR=null, searchT='';
434→
435→    function renderList() {
436→      const list = document.getElementById('spotList');
437→      list.innerHTML = '';
438→      let f = spots.filter(s => {
439→        if (curF!=='all' && !s.cat.includes(curF)) return false;
440→        if (curA!=='all' && s.area!==curA) return false;
441→        if (curR && (!s.r || !s.r.includes(curR))) return false;
442→        if (searchT && !s.name.includes(searchT) && !s.desc.includes(searchT)) return false;
443→        return true;
444→      });
445→      document.getElementById('spotCount').textContent = `${f.length} 个机位`;
446→      document.getElementById('sn').textContent = f.length;
447→      const g = {};
448→      f.forEach(s => { if (!g[s.area]) g[s.area]=[]; g[s.area].push(s); });
449→      AO.forEach(a => {
450→        if (!g[a]) return;
451→        const t = document.createElement('div'); t.className='sgt';
452→        t.textContent = `── ${AN[a]} (${g[a].length}) ──`;
453→        list.appendChild(t);
454→        g[a].forEach(s => {
455→          const c = document.createElement('div'); c.className='spot-card'; c.dataset.id=s.id;
456→          const th = s.tags.map((t,i) => `<span class="stag t-${s.tc[i]||'sea'}">${t}</span>`).join('');
457→          c.innerHTML = `<div class="sico" style="background:${CC[s.cat[0]]}18">${s.emoji}</div>
458→            <div class="sinfo"><div class="sname">${s.name}${s.hot?'<span class="hot">热门</span>':''}${s.pro?'<span class="pro">专业收录</span>':''}</div>
459→            <div class="sdesc">${s.desc}</div><div class="stags">${th}</div></div>`;
460→          c.addEventListener('click', () => flyTo(s.id));
461→          list.appendChild(c);
462→        });
463→      });
464→    }
465→
466→    document.querySelectorAll('.ftab').forEach(t => t.addEventListener('click', () => {
467→      document.querySelectorAll('.ftab').forEach(x=>x.classList.remove('active'));
468→      t.classList.add('active'); curF=t.dataset.f; renderList(); updateM();
469→    }));
470→    document.querySelectorAll('.atab').forEach(t => t.addEventListener('click', () => {
471→      document.querySelectorAll('.atab').forEach(x=>x.classList.remove('active'));
472→      t.classList.add('active'); curA=t.dataset.a; renderList(); updateM();
473→    }));
474→    document.querySelectorAll('.rbtn').forEach(t => t.addEventListener('click', () => {
475→      const was = t.classList.contains('active');
476→      document.querySelectorAll('.rbtn').forEach(x=>x.classList.remove('active'));
477→      curR = was ? null : t.dataset.r;
478→      if (curR) t.classList.add('active');
479→      renderList(); updateM();
480→    }));
481→    document.getElementById('searchBox').addEventListener('input', e => { searchT=e.target.value; renderList(); updateM(); });
482→
483→    function initMap() {
484→      map = L.map('map', { center:[36.062,120.420], zoom:11, zoomControl:false });
485→      L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { subdomains:'abcd', maxZoom:19 }).addTo(map);
486→      L.control.zoom({ position:'topright' }).addTo(map);
487→      spots.forEach(s => {
488→        const ic = L.divIcon({ className:'',
489→          html:`<div class="cm"><div class="ml">${s.name}</div><div class="mp" style="background:${CC[s.cat[0]]};${s.pro?'border:2px solid rgba(171,71,188,0.5);':''}"><span class="me">${s.emoji}</span></div></div>`,
490→          iconSize:[30,38], iconAnchor:[15,38], popupAnchor:[0,-38] });
491→        const m = L.marker([s.lat,s.lng], {icon:ic}).addTo(map);
492→        m.on('click', () => showInfo(s));
493→        markers[s.id] = m;
494→      });
495→    }
496→
497→    function updateM() {
498→      spots.forEach(s => {
499→        const m = markers[s.id]; if (!m) return;
500→        let show = true;
501→        if (curF!=='all' && !s.cat.includes(curF)) show=false;
502→        if (curA!=='all' && s.area!==curA) show=false;
503→        if (curR && (!s.r || !s.r.includes(curR))) show=false;
504→        if (searchT && !s.name.includes(searchT) && !s.desc.includes(searchT)) show=false;
505→        show ? map.addLayer(m) : map.removeLayer(m);
506→      });
507→    }
508→
509→    function flyTo(id) {
510→      const s = spots.find(x=>x.id===id); if (!s) return;
511→      map.flyTo([s.lat,s.lng], 15, { duration:0.8 });
512→      document.querySelectorAll('.spot-card').forEach(c=>c.classList.remove('active'));
513→      const c = document.querySelector(`.spot-card[data-id="${id}"]`);
514→      if (c) { c.classList.add('active'); c.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
515→      showInfo(s);
516→    }
517→
518→    function showInfo(s) {
519→      const p = document.getElementById('infoPanel');
520→      document.getElementById('iname').innerHTML = `${s.emoji} ${s.name} ${s.hot?'<span class="hot">热门</span>':''} ${s.pro?'<span class="pro">视觉中国/500px</span>':''}`;
521→      document.getElementById('idesc').textContent = s.desc;
522→      document.getElementById('idets').innerHTML = `
523→        <div class="idet"><div class="idet-l">📸 最佳时间</div><div class="idet-v">${s.bt}</div></div>
524→        <div class="idet"><div class="idet-l">🗓️ 最佳季节</div><div class="idet-v">${s.bs}</div></div>
525→        <div class="idet"><div class="idet-l">💡 拍摄建议</div><div class="idet-v">${s.tip}</div></div>`;
526→      const nav = `https://uri.amap.com/marker?position=${s.lng},${s.lat}&name=${encodeURIComponent(s.name)}&callnative=1`;
527→      const view = `https://www.amap.com/search?query=${encodeURIComponent(s.name+' 青岛')}&city=370200`;
528→      document.getElementById('iacts').innerHTML = `
529→        <a href="${nav}" target="_blank" class="ibtn p">📍 高德导航</a>
530→        <a href="${view}" target="_blank" class="ibtn">🗺️ 高德查看</a>`;
531→      p.classList.add('show');
532→    }
533→
534→    document.getElementById('iclose').addEventListener('click', () => { document.getElementById('infoPanel').classList.remove('show'); });
535→
536→    renderList();
537→    initMap();
538→  </script>
539→</body>
540→</html>
